import{_ as o,o as i,c as t,a5 as r}from"./chunks/framework.Cooo9kuv.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"848-软件文档文件夹快捷管理工具-列表版","日期":"2026-04-14T00:00:00.000Z","修改日期":"2026-04-14T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["文件及文件夹批处理"],"标签":["快捷方式管理","程序管理工具","项目管理工具"]},"headers":[{"level":3,"title":"功能说明","slug":"功能说明","link":"#功能说明","children":[]},{"level":3,"title":"1. 项目管理标签页","slug":"_1-项目管理标签页","link":"#_1-项目管理标签页","children":[]},{"level":3,"title":"2. 本地搜索标签页","slug":"_2-本地搜索标签页","link":"#_2-本地搜索标签页","children":[]},{"level":3,"title":"配置文件与备份机制","slug":"配置文件与备份机制","link":"#配置文件与备份机制","children":[]},{"level":3,"title":"程序截图","slug":"程序截图","link":"#程序截图","children":[]},{"level":3,"title":"演示视频","slug":"演示视频","link":"#演示视频","children":[]},{"level":3,"title":"使用示例一：管理某软件项目的全部资料","slug":"使用示例一-管理某软件项目的全部资料","link":"#使用示例一-管理某软件项目的全部资料","children":[]},{"level":3,"title":"步骤","slug":"步骤","link":"#步骤","children":[]},{"level":3,"title":"使用示例二：个人常用资料与工具面板","slug":"使用示例二-个人常用资料与工具面板","link":"#使用示例二-个人常用资料与工具面板","children":[]},{"level":3,"title":"步骤","slug":"步骤-1","link":"#步骤-1","children":[]},{"level":3,"title":"程序使用环境及相关说明","slug":"程序使用环境及相关说明","link":"#程序使用环境及相关说明","children":[]},{"level":3,"title":"常见问题（FAQ）","slug":"常见问题-faq","link":"#常见问题-faq","children":[]},{"level":3,"title":"程序使用说明","slug":"程序使用说明","link":"#程序使用说明","children":[]}],"relativePath":"md/文件及文件夹批处理/848-软件文档文件夹快捷管理工具-列表版.md","filePath":"md/文件及文件夹批处理/848-软件文档文件夹快捷管理工具-列表版.md"}'),n={name:"md/文件及文件夹批处理/848-软件文档文件夹快捷管理工具-列表版.md"};function e(s,l,a,g,c,d){return i(),t("div",null,[...l[0]||(l[0]=[r('<p>用来快速管理和本地文件/文件夹。<br> 你可以为每个项目创建一组「快捷按钮」，每个按钮可以对应一个 <strong>文件 / 文件夹 / 网页 URL</strong></p><p><strong>支持：</strong></p><ul><li><strong>一键打开</strong> 指定的文件/文件夹/网址</li><li><strong>拖拽文件/文件夹/URL 到按钮</strong> 即可完成绑定</li><li><strong>右键按钮</strong> 进行重命名、改颜色、删除该行等操作</li><li><strong>多项目切换</strong>，每个项目使用独立按钮配置</li><li><strong>本地搜索</strong> 功能，在项目目录和自定义路径中快速查找文件/文件夹</li></ul><p>**非常适合用来整理：**项目文档、素材、脚本、常用工具、教程链接等。</p><h3 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h3><h3 id="_1-项目管理标签页" tabindex="-1">1. 项目管理标签页 <a class="header-anchor" href="#_1-项目管理标签页" aria-label="Permalink to &quot;1. 项目管理标签页&quot;">​</a></h3><p>打开程序后默认进入 <strong>“项目管理”</strong> 标签页，主要区域包括：</p><ul><li><strong>顶部项目区域</strong><ul><li><strong>新建项目</strong>：创建一个新的项目标签（会在 <code>projects</code> 目录下建立同名文件夹）。</li><li><strong>添加自定义模块</strong>：为当前项目新增一行按钮（每行 2 个按钮）。</li><li><strong>一键恢复默认</strong>： <ul><li>将当前项目的自定义按钮数量重置为 <strong>50 个</strong>（25 行×2 列）。</li><li>清空当前项目所有按钮的路径、名称与颜色。</li></ul></li><li><strong>选择项目下拉框</strong>：选择当前正在编辑/使用的项目。</li><li><strong>项目标签栏</strong>：以 Tab 方式展示所有项目，可右键进行「重命名 / 删除」。</li></ul></li><li><strong>按钮区域（主体）</strong><ul><li>默认每个项目有 <strong>50 个按钮</strong>（25 行 × 2 列）。</li><li>每个按钮都可以绑定一个：文件 / 文件夹 / URL。</li><li>支持操作： <ul><li><strong>左键单击</strong>： <ul><li>若尚未绑定路径：弹出对话框选择文件/文件夹或输入 URL。</li><li>若已绑定路径：直接用系统默认程序打开文件/文件夹/网址。</li></ul></li><li><strong>右键按钮</strong>（自定义菜单）： <ul><li><strong>重新指定</strong>：重新选择该按钮的文件/文件夹/URL。</li><li><strong>重命名</strong>：自定义按钮显示名称。</li><li><strong>设置颜色</strong>：为按钮设置背景颜色（不同项目、不同按钮可用不同颜色做分组标记）。</li><li><strong>删除此行</strong>：删除当前按钮所在的整行（即两个按钮一起删）。 <ul><li>程序保证每个项目最少保留 <strong>50 个按钮</strong>。</li></ul></li><li><strong>恢复默认</strong>：只重置当前按钮（路径+名称+颜色清空）。</li></ul></li><li><strong>拖拽功能</strong>： <ul><li>直接把文件 / 文件夹 / 浏览器地址栏中的 URL 拖到某个按钮上，即可快速绑定。</li><li>拖动按钮可以换位置：按住按钮左键拖到另一个按钮上可交换两者位置。</li></ul></li></ul></li></ul></li></ul><h3 id="_2-本地搜索标签页" tabindex="-1">2. 本地搜索标签页 <a class="header-anchor" href="#_2-本地搜索标签页" aria-label="Permalink to &quot;2. 本地搜索标签页&quot;">​</a></h3><p>点击上方的 <strong>“本地搜索”</strong> 标签，可以对本地文件进行快速查找。</p><ul><li><strong>搜索输入与模式</strong><ul><li>文本框：输入文件名、文件夹名或扩展名关键字。</li><li>搜索模式： <ul><li><strong>模糊搜索</strong>：名称中包含关键字即可匹配。</li><li><strong>精准搜索</strong>： <ul><li>若输入包含 <code>.</code>，则按完整文件名匹配（例如 <code>main.py</code>）。</li><li>否则匹配不带扩展名的文件名（例如输入 <code>main</code> 会匹配 <code>main.py</code>、<code>main.txt</code> 中的 <code>main</code> 部分）。</li></ul></li><li><strong>扩展名搜索</strong>：按后缀查找（例如输入 <code>pdf</code> 或 <code>.pdf</code>）。</li></ul></li></ul></li><li><strong>搜索范围选项</strong><ul><li><strong>搜索所有项目下的文件及文件夹</strong>：会遍历 <code>projects</code> 目录下的所有子项目。</li><li><strong>搜索自定义文件夹下的文件或文件夹</strong>：在下方维护一个自定义搜索路径列表。</li></ul></li><li><strong>搜索路径列表</strong><ul><li><strong>添加搜索路径</strong>：选择某个文件夹作为额外的搜索目录。</li><li><strong>清除所有搜索路径</strong>：一键清空列表。</li><li>右键某条路径可「删除此路径」。</li></ul></li><li><strong>搜索结果表格</strong><ul><li>列：<strong>名称 / 路径 / 类型（文件/文件夹）</strong></li><li>支持操作： <ul><li><strong>双击行</strong>：直接打开文件或文件夹。</li><li><strong>右键菜单</strong>： <ul><li>打开文件/文件夹</li><li>复制路径</li><li>复制到…（调用系统文件复制）</li><li>移动到…（调用系统文件移动）</li></ul></li></ul></li></ul></li></ul><h3 id="配置文件与备份机制" tabindex="-1">配置文件与备份机制 <a class="header-anchor" href="#配置文件与备份机制" aria-label="Permalink to &quot;配置文件与备份机制&quot;">​</a></h3><ul><li>所有配置保存在 <strong><code>config.json</code></strong> 中。</li><li>每次保存配置前，程序会自动将旧配置备份为 <strong><code>config.json.bak</code></strong>，用于防止意外损坏。</li></ul><p>如果 <code>config.json</code> 被删除或损坏，可以将**<code>config.json.bak</code>** 文件的.bak删除，然后重新打开程序即可。</p><h3 id="程序截图" tabindex="-1">程序截图 <a class="header-anchor" href="#程序截图" aria-label="Permalink to &quot;程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251204214442176485588295161.jpg" alt=""></p><h3 id="演示视频" tabindex="-1">演示视频 <a class="header-anchor" href="#演示视频" aria-label="Permalink to &quot;演示视频&quot;">​</a></h3><h3 id="使用示例一-管理某软件项目的全部资料" tabindex="-1">使用示例一：管理某软件项目的全部资料 <a class="header-anchor" href="#使用示例一-管理某软件项目的全部资料" aria-label="Permalink to &quot;使用示例一：管理某软件项目的全部资料&quot;">​</a></h3><p><strong>需求场景</strong>：<br> 你有一个软件项目「订单管理系统」，其相关资料分散在不同位置：需求文档、UI 设计稿、接口文档、测试用例、打包输出目录、线上文档链接等，希望统一集中在一个界面一键打开。</p><h3 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h3><ol><li>在 <strong>“项目管理”</strong> 标签页中点击 <strong>“新建项目”</strong>，输入项目名称：<code>订单管理系统</code>。</li><li>在按钮区域中，选择第一个按钮： <ul><li>直接点击按钮 → 弹出「输入自定义路径和名称」窗口。</li><li>点击「选择文件」，选中项目的需求文档，例如：<br><code>D:\\Work\\OrderSystem\\docs\\需求文档.docx</code></li><li>名称留空则默认使用文件名，也可以自定义为「需求文档」。</li></ul></li><li>第二个按钮用于绑定 UI 设计文件夹： <ul><li>点击按钮 → 选择文件夹 → 选中：<br><code>D:\\Work\\OrderSystem\\UI设计</code></li><li>名称改为「UI 设计」。</li></ul></li><li>第三个按钮绑定接口文档的在线链接： <ul><li>点击按钮 → 在路径输入框中直接粘贴 URL：<br><code>[https://doc.example.com/order-api](https://doc.example.com/order-api)</code></li><li>名称设置为「接口文档」。</li></ul></li><li>为了更好区分模块： <ul><li>右键「需求文档」按钮 → 设置颜色为 <strong>蓝色</strong>。</li><li>右键「UI 设计」按钮 → 设置颜色为 <strong>绿色</strong>。</li><li>右键「接口文档」按钮 → 设置颜色为 <strong>橙色</strong>。</li></ul></li><li>随着项目资料增多，可以： <ul><li>使用 <strong>“添加自定义模块”</strong> 添加新行，继续绑定测试报告、上线脚本、打包目录、日志目录等。</li><li>使用拖拽将「最常用」的按钮拖到上面几行，减少滚动。</li></ul></li></ol><p>从此以后，你只需打开本程序，选中「订单管理系统」项目，点击对应按钮即可快速打开所有相关资料，无需在各个磁盘、浏览器收藏夹中来回查找。</p><hr><h3 id="使用示例二-个人常用资料与工具面板" tabindex="-1">使用示例二：个人常用资料与工具面板 <a class="header-anchor" href="#使用示例二-个人常用资料与工具面板" aria-label="Permalink to &quot;使用示例二：个人常用资料与工具面板&quot;">​</a></h3><p><strong>需求场景</strong>：<br> 你希望把自己经常用到的 <strong>学习资料、常用软件、网盘链接、常访网站</strong> 整理到一个统一面板，方便每天打开电脑后一键启动。</p><h3 id="步骤-1" tabindex="-1">步骤 <a class="header-anchor" href="#步骤-1" aria-label="Permalink to &quot;步骤&quot;">​</a></h3><ol><li>运行程序，在 <strong>“项目管理”</strong> 中新建项目：<code>日常工作面板</code>。</li><li>将下面这些项目绑定到不同的按钮： <ul><li>「学习资料」文件夹： <ul><li>点击按钮 → 选择文件夹：<br><code>E:\\学习\\Python教程</code></li><li>名称改为「Python 教程」。</li></ul></li><li>「常用软件」： <ul><li>将桌面上的某软件快捷方式（或 EXE 文件）<strong>直接拖到某个按钮</strong> 上： <ul><li>比如 <code>C:\\Program Files\\Typora\\Typora.exe</code> → 名称改为「Typora」。</li></ul></li></ul></li><li>「网盘链接」： <ul><li>点击按钮 → 在路径输入框中粘贴：<br><code>[https://pan.baidu.com/s/xxxxx](https://pan.baidu.com/s/xxxxx)</code></li><li>名称改为「个人网盘」。</li></ul></li><li>「常用网址」： <ul><li>比如博客、官网、教程网站，直接输 URL 即可。</li></ul></li></ul></li><li>使用右键 <strong>“设置颜色”</strong> 对按钮进行分组，比如： <ul><li>学习类资料：统一用 <strong>蓝色</strong>。</li><li>工具软件：统一用 <strong>灰色</strong>。</li><li>网盘/云服务：统一用 <strong>紫色</strong>。</li></ul></li><li>将最常用的按钮（如「个人网盘」「Typora」「Python 教程」）拖到最上面 2～3 行，以便快速点击。</li></ol><p>这样，这个项目就变成了一个「个人工作启动面板」，只需启动本程序，选择 <code>日常工作面板</code>，手机/浏览器/网盘/编辑器/文档都可以从这里一键打开。</p><h3 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p></blockquote><h3 id="常见问题-faq" tabindex="-1">常见问题（FAQ） <a class="header-anchor" href="#常见问题-faq" aria-label="Permalink to &quot;常见问题（FAQ）&quot;">​</a></h3><ul><li><strong>Q：按钮最少可以有多少个？</strong><br> A：每个项目默认有 50 个按钮（25 行×2 列），如果删除行后不足 50 个，程序会阻止继续删除，保证至少 50 个。</li><li><strong>Q：路径变了怎么办？</strong><br> A：右键按钮 → 选择「重新指定」，重新选择新位置即可。</li><li><strong>Q：配置文件损坏或想重置配置怎么办？</strong><br> A：可以先关闭程序，备份当前目录下的 <code>config.json</code> 和 <code>config.json.bak</code>，然后删除它们重新运行程序获得全新配置；如需恢复旧配置，可把 <code>.bak</code> 改名为 <code>config.json</code> 再启动程序。</li><li><strong>Q：能否同时在多个电脑使用？</strong><br> A：可以将 <code>jiaoben.py</code>、<code>config.json</code>、<code>projects</code> 整个目录一起拷贝，，即可获得同样的界面与配置。</li></ul><h3 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h3><p><strong>双击快捷方式使用即可</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251204215511176485651133033.png" alt=""></p><p><strong>文件夹内为主程序，使用时使用快捷方式即可，下方绿色的框出来的为程序文件，如果快捷方式失效，将这个文件发送到桌面快捷方式即可</strong></p><p><strong>框出来的其他文件及文件夹未程序启动后自动生成的文件</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251204215712176485663253983.jpg" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2199.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2199.html</a></p>',40)])])}const p=o(n,[["render",e]]);export{h as __pageData,p as default};
